// ui_dataset_card.js
const STATE = require('STATE')
const statedb = STATE(__filename)
const { get } = statedb(fallback_module)
const net = require('net_helper')

module.exports = ui_dataset_card

async function ui_dataset_card (opts, invite) {
  const { id, sdb } = await get(opts.sid)
  const { drive } = sdb

  const on = {
    style: inject,
    icons: iconject
  }

  const { io } = net(id)

  const el = document.createElement('div')
  const shadow = el.attachShadow({ mode: 'closed' })

  shadow.innerHTML = `
    <div class="ui-card">
      <div class="card-header">
        <span class="folder-icon"></span>
        <h1 class="card-title">Dark Theme colors</h1>
      </div>

      <div class="card-body">
        <div class="info-row">
          <span class="label">Type :</span>
          <span class="value">Content Dataset</span>
        </div>

        <div class="info-row">
          <span class="label">Used In :</span>
          <div class="badge-group">
            <span class="badge badge-purple">Card</span>
            <span class="badge badge-orange">Gallery</span>
            <span class="badge badge-yellow">Slider</span>
          </div>
        </div>

        <div class="info-row link-row">
          <span class="folder-sub-icon"></span>
          <a href="#" class="file-link">3 Files, 1 Folder</a>
        </div>

        <div class="info-row">
          <span class="label">Owner :</span>
          <span class="value">Cypher</span>
        </div>

        <div class="info-row">
          <span class="label">Update :</span>
          <span class="value">2 days ago</span>
        </div>
      </div>
    </div>
  `

  const sheet = new CSSStyleSheet()
  shadow.adoptedStyleSheets = [sheet]

  const folder_icon = shadow.querySelector('.folder-icon')
  const folder_sub_icon = shadow.querySelector('.folder-sub-icon')

  await sdb.watch(onbatch)

  if (invite) io.accept(invite)

  return el

  async function onbatch (batch) {
    for (const { type, paths } of batch) {
      const data = await Promise.all(
        paths.map(path => drive.get(path).then(file => file.raw))
      )

      const handler = on[type] || (() => {})
      handler({ data })
    }
  }

  function inject ({ data }) {
    sheet.replaceSync(data[0])
  }

  function iconject ({ data }) {
    // Expecting SVG data for the main folder icon and sub-folder icon
    const [mainFolderSvg = '', subFolderSvg = ''] = data 
    if (folder_icon) folder_icon.innerHTML = mainFolderSvg 
    if (folder_sub_icon) folder_sub_icon.innerHTML = subFolderSvg || mainFolderSvg
  }
}

function fallback_module () {
  return {
    api: fallback_instance,
    _: {
      net_helper: { $: '' }
    }
  }

  function fallback_instance () {
    return {
      _: {
        net_helper: {
          0: ''
        }
      },

      drive: {
        'icons/': {
          'folder.svg': { '$ref': 'folder.svg' }
        },

        'style/ui_dataset_card.css': {
          '$ref': 'ui_dataset_card.css'
        }
      }
    }
  }
}